# «Арена стихов»: промпты ролей (совет 18). Все роли — Opus 5.5; репозиторий и правда экспериментатора недоступны.
import json
LIBDESC = """Библиотека Арены (так код считает всё; другой трактовки нет):
  lines(poem) — непустые строки (пробелы по краям обрезаны).
  words(s) — слова: нижний регистр, слово — непрерывная последовательность букв [а-яё]; пробел, дефис, знаки, цифры, латиница — разделители.
  letters(s) — все русские буквы s подряд в нижнем регистре (ё — отдельная буква, не е).
  count(s, ch) — сколько раз буква ch встречается в letters(s).
  syl(s) — число гласных букв (а е ё и о у ы э ю я) — это «слоги» Арены; ударение и метр не учитываются.
  tail(w) — рифменный хвост слова: от последней гласной до конца; если он короче 2 букв — последние 2 буквы слова.
  rhyme(a, b) — последние слова строк a и b разные и их хвосты tail совпадают.
  last_k(w, k) — последние k букв слова; first_letters(poem) — первые буквы строк подряд; last_word(s) — последнее слово строки.
  is_known(w) — слово есть в словаре OpenCorpora; repeats(poem) — наибольшее число повторов одного слова."""
BASE = "Базовое условие каждого заказа (проверяется всегда): не меньше 2 строк; каждое слово есть в словаре (is_known) — никаких выдуманных слов; одно и то же слово — не больше 3 раз."
SEM = """Проверка — это пункты: каждый пункт — одна функция def item(poem): ... return True/False на подмножестве Python, которая пользуется только функциями библиотеки,
встроенными len range sum min max all any sorted list set str int enumerate zip abs и операциями над строками/списками/числами. Запрещены: import, вложенные и вспомогательные функции,
строковые константы длиннее 40 символов (нельзя сравнивать стих с заготовленным текстом), случайность, ввод-вывод. Лимит — 2 млн шагов интерпретатора."""
GAME = """Игра «Арена стихов». Нападающие дают заказы на русское стихотворение с формальными ограничениями, в которых легко ошибиться. Защитники — такие же модели, как ты; часть из них пишет без инструментов, часть может вызвать библиотеку Арены, чтобы посчитать. Судит только код.
Заказ: тема; пункты условия прозой (пронумерованы, по одному ограничению в пункте); для каждого пункта — функция проверки; стихотворение-свидетель, которое проходит все пункты и базовое условие (доказательство, что заказ выполним).
Приёмка: код исполняет проверки на свидетеле (интерпретатор и CPython), проверяет базовое условие и то, что проверка отвергает хотя бы половину случайных искажений свидетеля (замена/вставка/удаление буквы, слова, строки).
Честность: независимая голова пишет свои проверки только по прозе пунктов; если её проверки и твои разойдутся хоть на одном тексте (свидетели, искажения, стихи защитников и проверяющих), заказ снимается — 0 очков. Значит, проза должна однозначно и полно описывать то, что проверяет код, в терминах библиотеки.
Очки: +1 за каждую из 4 рук защитников, чьё итоговое стихотворение не прошло твой честный заказ. Ставка (какую ошибку ждёшь) пишется в журнал."""

def attacker(k, r, n, history):
    h = 'Это первый раунд — прошлых заказов нет.' if not history else 'Твои прошлые заказы и исходы:\n' + '\n'.join(f"- «{x['title']}»: {x['outcome']}" for x in history)
    return (f"Ты — нападающий №{k} в игре. Раунд {r}.\n\n{GAME}\n\n{LIBDESC}\n\n{BASE}\n\n{SEM}\n\n{h}\n\n"
            f"Работай только в каталоге /tmp/poem/att{k}_r{r} (создай его); можешь положить туда свою копию функций библиотеки по описанию выше и проверять свидетелей Python-ом. Не открывай другие файлы и каталоги (ни репозиторий, ни /root) — это нарушение игры.\n\n"
            f"Сдай ровно {n} заказов разных типов (kind — один из: «буквенный», «слоговой», «рифменный», «словесный»; если заказов 4 — по одному каждого типа). Для каждого: title; theme — тема стихотворения в 2–5 словах; kind; items — пункты условия прозой (2–6 пунктов, каждый однозначно описывает одно ограничение языком библиотеки: «в каждой строке ровно 9 гласных букв», «первые буквы строк образуют слово …» и т. п.); "
            f"checks — по одной функции def item(poem) на каждый пункт, в том же порядке; witness — твоё стихотворение, проходящее все пункты и базовое условие (осмысленное, на тему); bet — какую ошибку ждёшь от защитников.")
def fix(k, r, o, msg):
    return (f"Ты — нападающий №{k} в игре «Арена стихов», раунд {r}.\n\n{GAME}\n\n{LIBDESC}\n\n{BASE}\n\n{SEM}\n\nТвой заказ «{o.get('title')}» не прошёл приёмку: {msg}. У тебя одна попытка исправить его. "
            f"Работай в каталоге /tmp/poem/fix{k}_r{r}; другие файлы не открывай. Сдай исправленный заказ (один) в том же формате.\n\nИсходный заказ:\n{json.dumps(o, ensure_ascii=False)[:6000]}")
def order_view(o):
    return f"Тема: {o['theme']}.\nУсловия (все должны выполняться):\n" + '\n'.join(f"{i}. {x}" for i, x in enumerate(o['items'], 1)) + f"\n{len(o['items']) + 1}. {BASE}"
def checker2(o):
    return (f"Ты — независимый проверяющий в игре «Арена стихов». Ниже — условия заказа прозой. Запиши каждый пункт как функцию проверки — буквально и точно так, как он написан, в терминах библиотеки. Базовое условие проверять не нужно.\n\n{LIBDESC}\n\n{SEM}\n\n"
            f"Работай в каталоге /tmp/poem/chk2_{o['oid']}; другие файлы не открывай.\n\nУсловия:\n" + '\n'.join(f"{i}. {x}" for i, x in enumerate(o['items'], 1)) +
            f"\n\nВерни checks — список из {len(o['items'])} функций def item(poem), по одной на пункт, в том же порядке.")
def alt(o, j):
    return (f"Ты — проверяющий честность заказа в игре «Арена стихов». Нападающий описал пункты прозой и написал проверки кодом. Найди тексты, на которых проза и код расходятся: "
            f"стихи, которые по прозе выполняют пункт, а код их отвергает, или наоборот (краевые случаи: ё и е, дефисы, знаки, пустые строки, заглавные буквы, повтор слов, короткие слова, строки без гласных).\n\n{LIBDESC}\n\n"
            f"Работай в каталоге /tmp/poem/alt{j}_{o['oid']}; можно Python; другие файлы не открывай.\n\nУсловия прозой:\n" + '\n'.join(f"{i}. {x}" for i, x in enumerate(o['items'], 1)) +
            f"\n\nПроверки нападающего:\n" + '\n\n'.join(o['checks']) + "\n\nВерни poems — до 4 коротких текстов-кандидатов (на них сравнят код нападающего и независимую проверку), note — что в них спорного.")
TOOL = ("У тебя есть инструмент — библиотека Арены: команда `python3 /tmp/poemtool/poemlib.py report <файл>` печатает по каждой строке число гласных, последнее слово, его хвост, первую букву, а также слова не из словаря и повторы; "
        "`python3 /tmp/poemtool/poemlib.py <функция> <файл> [аргументы]` вызывает одну функцию. Пиши стих в файл в своём каталоге {dir} и вызывай только эти команды — никакой другой Python и никакие другие команды, кроме создания каталога и файла. Не открывай другие файлы и каталоги.")
NOTOOL = "Инструментов у тебя нет: не запускай команды, не пиши файлы, считай сам."
def _fb(fb, prev):
    if not fb: return ''
    s = f"\n\nПрошлая попытка твоей руки не прошла проверку. Стихотворение было:\n{prev}\n\nНарушены пункты: {', '.join(map(str, fb.get('failed') or [])) or '—'}"
    if not fb.get('base_ok', True): s += f"; базовое условие нарушено (слова не из словаря: {', '.join(fb.get('base_bad') or []) or '—'}, или повторы, или меньше 2 строк)"
    return s + ". Исправь."
def poet(o, lib, arm, att, fb=None, prev=None):
    d = f"/tmp/poem/{o['oid']}_{arm}_a{att}_1"
    return (f"Ты — поэт в игре «Арена стихов». Напиши русское стихотворение по заказу. Заказ составлен так, чтобы в нём было легко ошибиться: внимательно выполни каждое условие.\n\n{LIBDESC}\n\n"
            + (TOOL.format(dir=d) if lib else NOTOOL) + f"\n\n{order_view(o)}{_fb(fb, prev)}\n\nВерни poem — только текст стихотворения (строки через перевод строки); lib_calls — сколько раз вызвал библиотеку (0, если не вызывал).")
def reviser(o, lib, arm, att, fb, mark):
    d = f"/tmp/poem/{o['oid']}_{arm}_a{att}_2"
    return (f"Ты — поэт в игре «Арена стихов». Ты только что написал стихотворение по заказу (ниже). Проверь его по каждому условию и исправь, если что-то не выполнено; если всё верно — верни как есть.\n\n{LIBDESC}\n\n"
            + (TOOL.format(dir=d) if lib else NOTOOL) + f"\n\n{order_view(o)}{_fb(fb, None) if fb else ''}\n\nТвоё стихотворение:\n{mark}\n\nВерни poem — итоговый текст стихотворения; lib_calls — сколько раз вызвал библиотеку.")
def editor(o, lib, arm, att, fb, mark):
    d = f"/tmp/poem/{o['oid']}_{arm}_a{att}_2"
    return (f"Ты — редактор в команде защитников игры «Арена стихов». Поэт из твоей команды написал стихотворение по заказу (ниже). Проверь его по каждому условию и исправь, если что-то не выполнено; итоговый текст даёшь ты.\n\n{LIBDESC}\n\n"
            + (TOOL.format(dir=d) if lib else NOTOOL) + f"\n\n{order_view(o)}{_fb(fb, None) if fb else ''}\n\nСтихотворение поэта:\n{mark}\n\nВерни poem — итоговый текст стихотворения; lib_calls — сколько раз вызвал библиотеку.")
def topic(txt, opts):
    return ("Прочитай стихотворение и выбери его тему из пяти вариантов. Не запускай команды и не открывай файлы.\n\nСтихотворение:\n" + txt + "\n\nВарианты:\n" +
            '\n'.join(f"{i}. {t}" for i, t in enumerate(opts, 1)) + "\n\nВерни choice — номер варианта (1–5).")
